#!/usr/bin/env node
/**
 * tests/adversarial-gtv-m1-challenger.js
 * 
 * Empirical Adversarial Test Harness — Milestone 1 (R1: Visual Shell & Backdrop Rewrite)
 * Challenger: challenger_gtv_m1_2
 * 
 * Deep Stress Verification of:
 * - Suite 1: Backward Compatibility & DOM Invariants (getElementById, querySelector, classes, attributes)
 * - Suite 2: Top Bar Spatial Navigation & Focus Traversal across Tabs and Views
 * - Suite 3: Route Transitions, Focus Memory & Rapid Switch Synchronization
 * - Suite 4: Media Player DOM Integrity, OSD Element Preservation & Video Lifecycle
 * - Suite 5: Non-Negotiable Invariants (Services SHA-256, Zero DOM Sinks, Proxy Cascade, Luna Keepalive)
 */

'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const assert = require('assert');

// -----------------------------------------------------------------------------
// 1. Resolve JSDOM
// -----------------------------------------------------------------------------
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved:', e1.message);
      process.exit(1);
    }
  }
}

// -----------------------------------------------------------------------------
// 2. Terminal Styling & Reporting Infrastructure
// -----------------------------------------------------------------------------
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m'
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failureDetails = [];

async function check(suiteId, checkId, title, testFn) {
  totalChecks++;
  const label = `[${suiteId}.${checkId}] ${title}`;
  const start = Date.now();
  try {
    await testFn();
    passedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
  } catch (err) {
    failedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
    console.log(`      ${C.red}Error: ${err.message}${C.reset}`);
    failureDetails.push({ label, error: err.message, stack: err.stack });
  }
}

function makeRect(left, top, width, height) {
  return {
    left: left,
    top: top,
    right: left + width,
    bottom: top + height,
    width: width,
    height: height,
    x: left,
    y: top
  };
}

// -----------------------------------------------------------------------------
// 3. Harness Factory
// -----------------------------------------------------------------------------
function createHarness(options = {}) {
  const initialRoute = options.route || 'home';
  const htmlPath = path.resolve(__dirname, '../app/index.html');
  const configPath = path.resolve(__dirname, '../app/js/config.js');
  const navPath = path.resolve(__dirname, '../app/js/navigation.js');
  const appPath = path.resolve(__dirname, '../app/js/app.js');

  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, {
    url: 'http://localhost/#' + initialRoute,
    runScripts: 'outside-only'
  });
  const { window } = dom;

  // Polyfill scrolling
  window.Element.prototype.scrollIntoView = function () {};
  window.Element.prototype.scrollTo = function () {};

  // Accurate 1080p TV layout bounding boxes for spatial navigation
  window.Element.prototype.getBoundingClientRect = function () {
    const view = this.closest('.view');
    if (view && !view.classList.contains('active')) {
      return makeRect(0, 0, 0, 0);
    }
    if (this.style && (this.style.display === 'none' || this.style.visibility === 'hidden')) {
      return makeRect(0, 0, 0, 0);
    }

    const id = this.id;

    // Header items
    if (id === 'avatar' || this.classList.contains('brand-container')) {
      return makeRect(72, 44, 48, 48);
    }
    if (this.classList.contains('nav-pill-item') || this.classList.contains('tab')) {
      const route = this.getAttribute('data-route') || this.getAttribute('data-tab');
      if (route === 'home') return makeRect(760, 44, 96, 48);
      if (route === 'movies') return makeRect(864, 44, 96, 48);
      if (route === 'shows' || route === 'series') return makeRect(968, 44, 96, 48);
      if (route === 'search') return makeRect(1072, 44, 96, 48);
      return makeRect(760, 44, 96, 48);
    }
    if (id === 'top-btn-settings') {
      return makeRect(1752, 44, 48, 48);
    }

    // Home view items
    if (id === 'hero-play-btn') return makeRect(96, 460, 180, 56);
    if (id === 'hero-details-btn') return makeRect(292, 460, 140, 56);
    if (id === 'hero-list-btn') return makeRect(448, 460, 140, 56);
    if (this.classList.contains('card-provider')) return makeRect(96, 560, 160, 80);
    if (this.classList.contains('card-poster')) return makeRect(96, 680, 220, 330);

    // Details view items
    if (id === 'details-play-btn') return makeRect(96, 450, 180, 56);
    if (id === 'details-trailer-btn') return makeRect(292, 450, 160, 56);

    // Player view items
    if (id === 'player-back-btn' || id === 'osd-back-btn') return makeRect(96, 54, 56, 56);
    if (id === 'osd-rewind-btn') return makeRect(760, 940, 64, 64);
    if (id === 'osd-play-btn') return makeRect(928, 930, 80, 80);
    if (id === 'osd-forward-btn') return makeRect(1072, 940, 64, 64);
    if (id === 'osd-subtitles-btn') return makeRect(1500, 940, 56, 56);
    if (id === 'osd-audio-btn') return makeRect(1570, 940, 56, 56);
    if (id === 'osd-server-btn') return makeRect(1640, 940, 56, 56);

    // Search view virtual keyboard
    if (this.classList.contains('key-btn')) {
      const keyVal = this.getAttribute('data-key') || '';
      return makeRect(96 + (keyVal.charCodeAt(0) % 6) * 70, 200 + Math.floor(keyVal.charCodeAt(0) / 6) * 70, 60, 60);
    }

    return makeRect(96, 300, 100, 50);
  };

  // Mock HTMLMediaElement
  window.HTMLMediaElement.prototype.play = function () {
    this.paused = false;
    return Promise.resolve();
  };
  window.HTMLMediaElement.prototype.pause = function () {
    this.paused = true;
  };

  // Load scripts into DOM
  window.eval(fs.readFileSync(configPath, 'utf8'));
  window.eval(fs.readFileSync(navPath, 'utf8'));
  window.eval(fs.readFileSync(appPath, 'utf8'));

  if (window.CinejoyApp && typeof window.CinejoyApp.init === 'function') {
    window.CinejoyApp.init();
  }

  return {
    dom,
    window,
    document: window.document,
    app: window.CinejoyApp,
    spatialNav: window.SpatialNav
  };
}

// -----------------------------------------------------------------------------
// 4. Test Suites Implementation
// -----------------------------------------------------------------------------
async function runAllAdversarialTests() {
  console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`${C.bold}${C.cyan}► ADVERSARIAL STRESS TEST HARNESS — MILESTONE 1 VERIFICATION${C.reset}`);
  console.log(`${C.bold}${C.cyan}  Agent: challenger_gtv_m1_2 | Focus: Navigation, Compatibility, Player${C.reset}`);
  console.log(`${C.bold}${C.cyan}========================================================================${C.reset}\n`);

  // ===========================================================================
  // SUITE 1: Backward Compatibility & DOM Invariants
  // ===========================================================================
  console.log(`${C.bold}${C.magenta}▶ SUITE 1: Backward Compatibility & Header DOM Invariants${C.reset}`);

  await check('S1', '1', 'document.getElementById("app-header") resolves to <header id="top">', async () => {
    const { document } = createHarness();
    const header = document.getElementById('app-header');
    assert(header, 'getElementById("app-header") returned falsy');
    assert.strictEqual(header.tagName, 'HEADER');
    assert.strictEqual(header.id, 'top');
    assert(header.classList.contains('app-header'), 'Header must retain .app-header class');
    assert.strictEqual(header.getAttribute('role'), 'banner');
  });

  await check('S1', '2', 'document.getElementById("header-brand") resolves to #avatar profile indicator', async () => {
    const { document } = createHarness();
    const brand = document.getElementById('header-brand');
    assert(brand, 'getElementById("header-brand") returned falsy');
    assert.strictEqual(brand.id, 'avatar');
    assert(brand.classList.contains('brand-container'), 'Brand must retain .brand-container class');
  });

  await check('S1', '3', 'Direct ID resolution for #top and #avatar functions without mutation', async () => {
    const { document } = createHarness();
    const top = document.getElementById('top');
    const avatar = document.getElementById('avatar');
    assert(top && top.tagName === 'HEADER');
    assert(avatar && avatar.id === 'avatar');
  });

  await check('S1', '4', 'Adversarial getElementById calls (null, undefined, non-strings, unbound)', async () => {
    const { document } = createHarness();
    assert.strictEqual(document.getElementById(null), null);
    assert.strictEqual(document.getElementById(undefined), null);
    assert.strictEqual(document.getElementById(''), null);
    assert.strictEqual(document.getElementById('non-existent-xyz-999'), null);

    // Call and Apply invocation styles
    const viaCall = document.getElementById.call(document, 'app-header');
    assert(viaCall && viaCall.id === 'top');
    const viaApply = document.getElementById.apply(document, ['app-header']);
    assert(viaApply && viaApply.id === 'top');

    // Method extraction / unbound invocation
    const detachedGebi = document.getElementById;
    const detachedResult = detachedGebi('app-header');
    assert(detachedResult && detachedResult.id === 'top', 'Unbound getElementById must resolve #app-header');
  });

  await check('S1', '5', 'document.querySelector query compatibility for .app-header and #top', async () => {
    const { document } = createHarness();
    const qHeader = document.querySelector('.app-header');
    const qTop = document.querySelector('#top');
    const qAvatar = document.querySelector('.brand-container');
    assert(qHeader && qHeader.id === 'top');
    assert(qTop && qTop.classList.contains('app-header'));
    assert(qAvatar && qAvatar.id === 'avatar');
  });

  await check('S1', '6', 'Full-Bleed Backdrop System DOM structure (#bg, #bgA, #bgB, #bgBlur, #shade)', async () => {
    const { document } = createHarness();
    const bg = document.getElementById('bg');
    const bgA = document.getElementById('bgA');
    const bgB = document.getElementById('bgB');
    const bgBlur = document.getElementById('bgBlur');
    const shade = document.getElementById('shade');

    assert(bg, '#bg backdrop container missing');
    assert(bgA, '#bgA layer missing');
    assert(bgB, '#bgB layer missing');
    assert(bgBlur, '#bgBlur ambient layer missing');
    assert(shade, '#shade scrim missing');

    assert(bgA.classList.contains('on'), '#bgA should have .on class initially');
    assert(shade.classList.contains('dual-gradient-overlay'), '#shade must have dual-gradient-overlay');
  });

  await check('S1', '7', 'CSS Design Tokens & Scrim Dual-Gradient Rules', async () => {
    const tokensCss = fs.readFileSync(path.resolve(__dirname, '../app/css/tokens.css'), 'utf8');
    const layoutCss = fs.readFileSync(path.resolve(__dirname, '../app/css/layout.css'), 'utf8');

