  // ===========================================================================
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 2: Top Bar Spatial Navigation & Focus Traversal${C.reset}`);

  await check('S2', '1', 'Header candidates discovery: exactly 4 tabs navigable, non-nav pills excluded', async () => {
    const { spatialNav, document } = createHarness();
    const candidates = spatialNav.getCandidates();
    const headerCandidates = candidates.filter(c => c.getAttribute('data-nav-group') === 'header');

    assert.strictEqual(headerCandidates.length, 4, `Expected 4 header candidates, got ${headerCandidates.length}`);
    const ids = headerCandidates.map(c => c.id);
    assert(ids.includes('header-nav-home'), 'Missing #header-nav-home');
    assert(ids.includes('header-nav-movies'), 'Missing #header-nav-movies');
    assert(ids.includes('header-nav-series'), 'Missing #header-nav-series');
    assert(ids.includes('header-nav-search'), 'Missing #header-nav-search');

    // Confirm avatar and settings are excluded from spatial nav candidates
    assert(!ids.includes('avatar'), 'Avatar must NOT be in navigable candidates');
    assert(!ids.includes('top-btn-settings'), 'Settings must NOT be in navigable candidates');
