  await check('S2', '5', 'Key Repeat Burst Hammering: 50 Rapid Keypresses Maintain Engine Stability', async () => {
    const { spatialNav, document } = createHarness();
    const homeTab = document.getElementById('header-nav-home');
    spatialNav.setFocus(homeTab);

    const directions = ['right', 'left', 'right', 'down', 'up'];
    for (let i = 0; i < 50; i++) {
      spatialNav.move(directions[i % directions.length]);
    }
    const finalFocus = spatialNav.getCurrentFocus();
    assert(finalFocus, 'Engine must retain valid focused element after 50 rapid key bursts');
