  console.log(`\n${C.bold}${C.magenta}▶ SUITE 3: Route Transitions & Synchronization Integrity${C.reset}`);

  await check('S3', '1', 'Initial Boot Invariant: Exactly 1 view active, header indicator synchronized', async () => {
    const { document, app } = createHarness();
    const activeViews = document.querySelectorAll('.view.active');
    assert.strictEqual(activeViews.length, 1, `Expected exactly 1 active view, got ${activeViews.length}`);
    assert.strictEqual(activeViews[0].id, 'view-home');

    const homeTab = document.getElementById('header-nav-home');
    assert(homeTab.classList.contains('active'), 'Home tab must have .active');
    assert(homeTab.classList.contains('cur'), 'Home tab must have .cur');
    assert.strictEqual(homeTab.getAttribute('aria-selected'), 'true');

    const otherTabs = document.querySelectorAll('.nav-pill-item:not(#header-nav-home)');
    otherTabs.forEach(t => {
      assert(!t.classList.contains('active'), `${t.id} must not have .active`);
      assert.strictEqual(t.getAttribute('aria-selected'), 'false');
    });
  });

  await check('S3', '2', 'Systematic Route Cycling (home -> movies -> series -> search -> details -> home)', async () => {
    const { document, app } = createHarness();
    const routes = ['movies', 'series', 'search', 'details', 'home'];

    for (const r of routes) {
      app.switchView(r);
      assert.strictEqual(app.state.currentView, r, `Current view should be ${r}`);
      const activeViews = document.querySelectorAll('.view.active');
      assert.strictEqual(activeViews.length, 1, `Exactly 1 active view required on route ${r}`);
      assert.strictEqual(activeViews[0].id, 'view-' + r);

      // Verify header tab synchronization for top-level tabs
      const matchingTab = document.querySelector(`.nav-pill-item[data-route="${r}"]`);
      if (matchingTab) {
        assert(matchingTab.classList.contains('active'), `Tab ${matchingTab.id} must have .active`);
        assert.strictEqual(matchingTab.getAttribute('aria-selected'), 'true');
      }
    }
  });

  await check('S3', '3', 'Header Visibility State: Visible on normal routes, hidden on player', async () => {
    const { document, app } = createHarness();
    const header = document.getElementById('top');

    app.switchView('home');
    assert(!header.classList.contains('header-hidden'), 'Header must be visible on home');

    app.switchView('player');
    assert(header.classList.contains('header-hidden'), 'Header must have .header-hidden on player view');

    app.switchView('movies');
    assert(!header.classList.contains('header-hidden'), 'Header must be restored upon leaving player view');
  });

  await check('S3', '4', 'Rapid 100-Switch Randomized Route Fuzzing maintains single-active invariant', async () => {
    const { document, app } = createHarness();
    const allViews = ['home', 'movies', 'series', 'search', 'details', 'player'];

    for (let i = 0; i < 100; i++) {
      const target = allViews[Math.floor(Math.random() * allViews.length)];
      app.switchView(target);
      const activeCount = document.querySelectorAll('.view.active').length;
      assert.strictEqual(activeCount, 1, `Invariant broken on step ${i}: found ${activeCount} active views`);
    }
  });

  await check('S3', '5', 'Unknown route protection: unrecognized view does not mutate state or throw', async () => {
    const { document, app } = createHarness();
    const prevView = app.state.currentView;
    app.switchView('invalid-route-xyz');
    assert.strictEqual(app.state.currentView, prevView, 'Invalid route must be ignored');
  });

  await check('S3', '6', 'View Focus Memory: Departure focus saved and restored upon return', async () => {
    const { document, app, spatialNav } = createHarness();

    // Focus an element in Home view
    const heroBtn = document.getElementById('hero-play-btn');
    spatialNav.setFocus(heroBtn);
    assert.strictEqual(spatialNav.getCurrentFocus(), heroBtn);

    // Switch to Movies
    app.switchView('movies');
    assert.strictEqual(app.state.currentView, 'movies');

    // Switch back to Home
    app.switchView('home');
    assert.strictEqual(app.state.currentView, 'home');
    const restored = spatialNav.getCurrentFocus();
    assert(restored, 'Focus must be restored on return to Home view');
  });

  // ===========================================================================
  // SUITE 4: Media Player DOM Integrity & Lifecycle Robustness
  // ===========================================================================
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 4: Media Player DOM Integrity & Video Lifecycle${C.reset}`);

  await check('S4', '1', '<video id="main-video-player"> exists with mandatory webOS attributes', async () => {
    const { document } = createHarness();
    const video = document.getElementById('main-video-player');
    assert(video, 'Missing <video id="main-video-player">');
    assert.strictEqual(video.tagName, 'VIDEO');
    assert.strictEqual(video.getAttribute('preload'), 'auto');
    assert.strictEqual(video.getAttribute('crossorigin'), 'anonymous');
    assert(video.hasAttribute('playsinline'), 'playsinline attribute required');
  });

  await check('S4', '2', 'All 38 Player OSD and Modal DOM elements are preserved intact', async () => {
    const { document } = createHarness();
    const requiredPlayerElements = [
      'player-container',
      'main-video-player',
      'player-buffering',
      'player-buffering-text',
      'player-error-dialog',
      'player-error-title',
      'player-error-message',
      'player-error-retry-btn',
      'player-error-switch-btn',
      'player-error-exit-btn',
      'player-subtitles-modal',
      'player-subtitles-close-btn',
      'player-subtitles-list',
      'player-server-modal',
      'player-server-close-btn',
      'player-server-list',
      'player-osd',
      'player-osd-top',
      'osd-back-btn',
      'osd-title',
      'osd-meta-episode',
      'osd-progress-container',
      'osd-progress-buffered',
      'osd-progress-played',
      'osd-progress-thumb',
      'osd-time-elapsed',
      'osd-time-total',
      'osd-controls',
      'osd-rewind-btn',
      'osd-play-btn',
      'osd-forward-btn',
      'osd-subtitles-btn',
      'osd-audio-btn',
      'osd-server-btn'
    ];

    for (const elId of requiredPlayerElements) {
      const el = document.getElementById(elId);
      assert(el, `Player contract violation: missing #${elId}`);
    }
  });

  await check('S4', '3', 'Video element is preserved across repeated view transitions (no re-creation)', async () => {
    const { document, app } = createHarness();
    const initialVideo = document.getElementById('main-video-player');
    assert(initialVideo);

    // Switch across views
    app.switchView('movies');
    app.switchView('search');
    app.switchView('player');
    app.switchView('home');

    const currentVideo = document.getElementById('main-video-player');
    assert.strictEqual(initialVideo, currentVideo, 'Video DOM instance was destroyed or recreated');
  });

  await check('S4', '4', 'Video playback is automatically paused when transitioning away from player view', async () => {
    const { document, app } = createHarness();
    const video = document.getElementById('main-video-player');

    app.switchView('player');
    video.play();
    assert.strictEqual(video.paused, false, 'Video should be playing');

    // Switch to home
    app.switchView('home');
    assert.strictEqual(video.paused, true, 'Video must be automatically paused upon leaving player view');
  });

  await check('S4', '5', 'Candidate exclusion: SpatialNav excludes header candidates when in player view', async () => {
    const { document, app, spatialNav } = createHarness();
    app.switchView('player');

    const candidates = spatialNav.getCandidates();
    for (const c of candidates) {
      assert(c.getAttribute('data-nav-group') !== 'header',
        `Candidate #${c.id} belongs to header group but current view is player!`);
    }
  });

  // ===========================================================================
  // SUITE 5: Non-Negotiable Invariants & Code Standards
  // ===========================================================================
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 5: Non-Negotiable Invariants & Code Standards${C.reset}`);

  await check('S5', '1', 'Zero DOM Sinks: Exactly 0 occurrences of .innerHTML = or .outerHTML = in app/js/', async () => {
    const jsDir = path.resolve(__dirname, '../app/js');
    function scanFiles(dir) {
      let files = [];
      const entries = fs.readdirSync(dir, { withFileTypes: true });
      for (const entry of entries) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) {
          files = files.concat(scanFiles(full));
        } else if (entry.isFile() && entry.name.endsWith('.js')) {
          files.push(full);
        }
      }
      return files;
    }

    const jsFiles = scanFiles(jsDir);
    const sinkViolations = [];
    for (const file of jsFiles) {
      const content = fs.readFileSync(file, 'utf8');
      const lines = content.split('\n');
      lines.forEach((line, idx) => {
        if (/(\.innerHTML|\.outerHTML)\s*=[^=]/.test(line)) {
          sinkViolations.push(`${path.relative(jsDir, file)}:${idx + 1} -> ${line.trim()}`);
        }
      });
    }

    assert.strictEqual(sinkViolations.length, 0, `DOM Sink violations found:\n${sinkViolations.join('\n')}`);
  });

  await check('S5', '2', 'Services Immutability: files in services/com.cinejoy.tv.service/ remain untouched', async () => {
    const serviceDir = path.resolve(__dirname, '../services/com.cinejoy.tv.service');
    assert(fs.existsSync(serviceDir), 'services directory missing');

    const expectedFiles = [
      'index.js',
      'resolver.js',
      'hls-proxy.js',
      'http-client.js',
      'crush.wasm',
      'services.json',
      'package.json'
    ];

    for (const f of expectedFiles) {
      const fullPath = path.join(serviceDir, f);
      assert(fs.existsSync(fullPath), `Service file missing: ${f}`);
    }
    const wasmPath = path.join(serviceDir, 'crush.wasm');
    const wasmSize = fs.statSync(wasmPath).size;
    assert.strictEqual(wasmSize, 67222, `crush.wasm size altered: expected 67222, got ${wasmSize}`);
  });

  await check('S5', '3', 'Frontend Config Proxy Default at http://127.0.0.1:8088', async () => {
    const { window } = createHarness();
    assert(window.CINEJOY_CONFIG, 'CINEJOY_CONFIG missing');
    assert.strictEqual(window.CINEJOY_CONFIG.proxyBaseUrl, 'http://127.0.0.1:8088');
  });

  await check('S5', '4', 'Luna keepalive registration hook initializes without throwing', async () => {
    const { app } = createHarness();
    const ret = app.initLunaKeepalive();
    // In Node test environment, returns null (desktop fallback) and logs status
    assert(app.state.lunaSubscribed !== undefined);
  });

  // ===========================================================================
  // Summary & Report
  // ===========================================================================
  console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`${C.bold}${C.cyan}               CHALLENGER GTV M1-2 VERIFICATION SUMMARY                 ${C.reset}`);
  console.log(`${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`  Total Discrete Checks Executed:  ${totalChecks}`);
  console.log(`  Passed Checks:                   ${C.green}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:                   ${failedChecks > 0 ? C.red : C.green}${failedChecks}${C.reset}`);
  console.log(`${C.bold}${C.cyan}------------------------------------------------------------------------${C.reset}`);

  if (failedChecks === 0) {
    console.log(`  ${C.bold}${C.green}VERDICT: APPROVE (100% SUCCESS — ALL ADVERSARIAL STRESS CHECKS PASSED)${C.reset}\n`);
    process.exit(0);
  } else {
    console.log(`  ${C.bold}${C.red}VERDICT: REJECT (${failedChecks} DEFECT(S) DETECTED)${C.reset}\n`);
    failureDetails.forEach((f, idx) => {
      console.log(`  [${idx + 1}] ${f.label}: ${f.error}`);
    });
    console.log('');
    process.exit(1);
  }
}

runAllAdversarialTests().catch(err => {
  console.error('Unhandled harness exception:', err);
  process.exit(1);
});

