#!/usr/bin/env node
/**
 * tests/adversarial-gtv-m1-challenger.js
 * 
 * Empirical Adversarial Test Harness — Milestone 1 (R1: Visual Shell & Backdrop Rewrite)
 * Challenger: challenger_gtv_m1_2
 * 
 * Deep Stress Verification of:
 * - Suite 1: Backward Compatibility & DOM Invariants (getElementById, querySelector, classes, attributes)
 * - Suite 2: Top Bar Spatial Navigation & Focus Traversal across Tabs and Views
 * - Suite 3: Route Transitions, Focus Memory & Rapid Switch Synchronization
 * - Suite 4: Media Player DOM Integrity, OSD Element Preservation & Video Lifecycle
 * - Suite 5: Non-Negotiable Invariants (Services SHA-256, Zero DOM Sinks, Proxy Cascade, Luna Keepalive)
 */

'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const assert = require('assert');

// -----------------------------------------------------------------------------
// 1. Resolve JSDOM
// -----------------------------------------------------------------------------
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved:', e1.message);
      process.exit(1);
    }
  }
}

// -----------------------------------------------------------------------------
// 2. Terminal Styling & Reporting Infrastructure
// -----------------------------------------------------------------------------
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m'
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failureDetails = [];

async function check(suiteId, checkId, title, testFn) {
  totalChecks++;
  const label = `[${suiteId}.${checkId}] ${title}`;
  const start = Date.now();
  try {
    await testFn();
    passedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
  } catch (err) {
    failedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
    console.log(`      ${C.red}Error: ${err.message}${C.reset}`);
    failureDetails.push({ label, error: err.message, stack: err.stack });
  }
}

function makeRect(left, top, width, height) {
  return {
    left: left,
    top: top,
    right: left + width,
    bottom: top + height,
    width: width,
    height: height,
    x: left,
    y: top
  };
}

// -----------------------------------------------------------------------------
// 3. Harness Factory
// -----------------------------------------------------------------------------
function createHarness(options = {}) {
  const initialRoute = options.route || 'home';
  const htmlPath = path.resolve(__dirname, '../app/index.html');
  const configPath = path.resolve(__dirname, '../app/js/config.js');
  const navPath = path.resolve(__dirname, '../app/js/navigation.js');
  const appPath = path.resolve(__dirname, '../app/js/app.js');

  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, {
    url: 'http://localhost/#' + initialRoute,
    runScripts: 'outside-only'
  });
  const { window } = dom;

  // Polyfill scrolling
  window.Element.prototype.scrollIntoView = function () {};
  window.Element.prototype.scrollTo = function () {};

  // Accurate 1080p TV layout bounding boxes for spatial navigation
  window.Element.prototype.getBoundingClientRect = function () {
    const view = this.closest('.view');
    if (view && !view.classList.contains('active')) {
      return makeRect(0, 0, 0, 0);
    }
    if (this.style && (this.style.display === 'none' || this.style.visibility === 'hidden')) {
      return makeRect(0, 0, 0, 0);
    }

    const id = this.id;

    // Header items
    if (id === 'avatar' || this.classList.contains('brand-container')) {
      return makeRect(72, 44, 48, 48);
    }
    if (this.classList.contains('nav-pill-item') || this.classList.contains('tab')) {
      const route = this.getAttribute('data-route') || this.getAttribute('data-tab');
      if (route === 'home') return makeRect(760, 44, 96, 48);
      if (route === 'movies') return makeRect(864, 44, 96, 48);
      if (route === 'shows' || route === 'series') return makeRect(968, 44, 96, 48);
      if (route === 'search') return makeRect(1072, 44, 96, 48);
      return makeRect(760, 44, 96, 48);
    }
    if (id === 'top-btn-settings') {
      return makeRect(1752, 44, 48, 48);
    }

    // Home view items
    if (id === 'hero-play-btn') return makeRect(96, 460, 180, 56);
    if (id === 'hero-details-btn') return makeRect(292, 460, 140, 56);
    if (id === 'hero-list-btn') return makeRect(448, 460, 140, 56);
    if (this.classList.contains('card-provider')) return makeRect(96, 560, 160, 80);
    if (this.classList.contains('card-poster')) return makeRect(96, 680, 220, 330);

    // Details view items
    if (id === 'details-play-btn') return makeRect(96, 450, 180, 56);
    if (id === 'details-trailer-btn') return makeRect(292, 450, 160, 56);

    // Player view items
    if (id === 'player-back-btn' || id === 'osd-back-btn') return makeRect(96, 54, 56, 56);
    if (id === 'osd-rewind-btn') return makeRect(760, 940, 64, 64);
    if (id === 'osd-play-btn') return makeRect(928, 930, 80, 80);
    if (id === 'osd-forward-btn') return makeRect(1072, 940, 64, 64);
    if (id === 'osd-subtitles-btn') return makeRect(1500, 940, 56, 56);
    if (id === 'osd-audio-btn') return makeRect(1570, 940, 56, 56);
    if (id === 'osd-server-btn') return makeRect(1640, 940, 56, 56);

    // Search view virtual keyboard
    if (this.classList.contains('key-btn')) {
      const keyVal = this.getAttribute('data-key') || '';
      return makeRect(96 + (keyVal.charCodeAt(0) % 6) * 70, 200 + Math.floor(keyVal.charCodeAt(0) / 6) * 70, 60, 60);
    }

    return makeRect(96, 300, 100, 50);
  };

  // Mock HTMLMediaElement with proper getter/setter for paused state
  Object.defineProperty(window.HTMLMediaElement.prototype, 'paused', {
    get: function () {
      return this._mockPaused !== undefined ? this._mockPaused : true;
    },
    set: function (val) {
      this._mockPaused = Boolean(val);
    },
    configurable: true
  });
  window.HTMLMediaElement.prototype.play = function () {
    this._mockPaused = false;
    return Promise.resolve();
  };
  window.HTMLMediaElement.prototype.pause = function () {
    this._mockPaused = true;
  };

  // Load scripts into DOM
  window.eval(fs.readFileSync(configPath, 'utf8'));
  window.eval(fs.readFileSync(navPath, 'utf8'));
  window.eval(fs.readFileSync(appPath, 'utf8'));

  if (window.CinejoyApp && typeof window.CinejoyApp.init === 'function') {
    window.CinejoyApp.init();
  }

  return {
    dom,
    window,
    document: window.document,
    app: window.CinejoyApp,
    spatialNav: window.SpatialNav
  };
}

// -----------------------------------------------------------------------------
// 4. Test Suites Implementation
// -----------------------------------------------------------------------------
async function runAllAdversarialTests() {
  console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
  console.log(`${C.bold}${C.cyan}► ADVERSARIAL STRESS TEST HARNESS — MILESTONE 1 VERIFICATION${C.reset}`);
  console.log(`${C.bold}${C.cyan}  Agent: challenger_gtv_m1_2 | Focus: Navigation, Compatibility, Player${C.reset}`);
  console.log(`${C.bold}${C.cyan}========================================================================${C.reset}\n`);

  // ===========================================================================
  // SUITE 1: Backward Compatibility & DOM Invariants
  // ===========================================================================
  console.log(`${C.bold}${C.magenta}▶ SUITE 1: Backward Compatibility & Header DOM Invariants${C.reset}`);

  await check('S1', '1', 'document.getElementById("app-header") resolves to <header id="top">', async () => {
    const { document } = createHarness();
    const header = document.getElementById('app-header');
    assert(header, 'getElementById("app-header") returned falsy');
    assert.strictEqual(header.tagName, 'HEADER');
    assert.strictEqual(header.id, 'top');
    assert(header.classList.contains('app-header'), 'Header must retain .app-header class');
    assert.strictEqual(header.getAttribute('role'), 'banner');
  });

  await check('S1', '2', 'document.getElementById("header-brand") resolves to #avatar profile indicator', async () => {
    const { document } = createHarness();
    const brand = document.getElementById('header-brand');
    assert(brand, 'getElementById("header-brand") returned falsy');
    assert.strictEqual(brand.id, 'avatar');
    assert(brand.classList.contains('brand-container'), 'Brand must retain .brand-container class');
  });

  await check('S1', '3', 'Direct ID resolution for #top and #avatar functions without mutation', async () => {
    const { document } = createHarness();
    const top = document.getElementById('top');
    const avatar = document.getElementById('avatar');
    assert(top && top.tagName === 'HEADER');
    assert(avatar && avatar.id === 'avatar');
  });

  await check('S1', '4', 'Adversarial getElementById calls (null, undefined, non-strings, unbound)', async () => {
    const { document } = createHarness();
    assert.strictEqual(document.getElementById(null), null);
    assert.strictEqual(document.getElementById(undefined), null);
    assert.strictEqual(document.getElementById(''), null);
    assert.strictEqual(document.getElementById('non-existent-xyz-999'), null);

    // Call and Apply invocation styles
    const viaCall = document.getElementById.call(document, 'app-header');
    assert(viaCall && viaCall.id === 'top');
    const viaApply = document.getElementById.apply(document, ['app-header']);
    assert(viaApply && viaApply.id === 'top');

    // Method extraction / unbound invocation
    const detachedGebi = document.getElementById;
    const detachedResult = detachedGebi('app-header');
    assert(detachedResult && detachedResult.id === 'top', 'Unbound getElementById must resolve #app-header');
  });

  await check('S1', '5', 'document.querySelector query compatibility for .app-header and #top', async () => {
    const { document } = createHarness();
    const qHeader = document.querySelector('.app-header');
    const qTop = document.querySelector('#top');
    const qAvatar = document.querySelector('.brand-container');
    assert(qHeader && qHeader.id === 'top');
    assert(qTop && qTop.classList.contains('app-header'));
    assert(qAvatar && qAvatar.id === 'avatar');
  });

  await check('S1', '6', 'Full-Bleed Backdrop System DOM structure (#bg, #bgA, #bgB, #bgBlur, #shade)', async () => {
    const { document } = createHarness();
    const bg = document.getElementById('bg');
    const bgA = document.getElementById('bgA');
    const bgB = document.getElementById('bgB');
    const bgBlur = document.getElementById('bgBlur');
    const shade = document.getElementById('shade');

    assert(bg, '#bg backdrop container missing');
    assert(bgA, '#bgA layer missing');
    assert(bgB, '#bgB layer missing');
    assert(bgBlur, '#bgBlur ambient layer missing');
    assert(shade, '#shade scrim missing');

    assert(bgA.classList.contains('on'), '#bgA should have .on class initially');
    assert(shade.classList.contains('dual-gradient-overlay'), '#shade must have dual-gradient-overlay');
  });

  await check('S1', '7', 'CSS Design Tokens & Scrim Dual-Gradient Rules', async () => {
    const tokensCss = fs.readFileSync(path.resolve(__dirname, '../app/css/tokens.css'), 'utf8');
    const layoutCss = fs.readFileSync(path.resolve(__dirname, '../app/css/layout.css'), 'utf8');

    assert(/--color-bg-base:\s*#0e1014/i.test(tokensCss), 'tokens.css must declare --color-bg-base: #0e1014');
    assert(/--cinema-bg-base:\s*#0e1014/i.test(tokensCss), 'tokens.css must declare --cinema-bg-base: #0e1014');
    assert(/transition:\s*opacity\s+\.9s\s+ease/i.test(layoutCss), 'layout.css must specify opacity .9s ease on backdrop image');

    const compactCss = layoutCss.replace(/\s+/g, '');
    assert(compactCss.includes('linear-gradient(90deg,rgba(14,16,20,0.95)0%,rgba(14,16,20,0.70)32%,rgba(14,16,20,0)62%)'),
      'layout.css missing Google TV horizontal scrim gradient');
    assert(compactCss.includes('linear-gradient(0deg,#0e101430%,rgba(14,16,20,0.60)48%,rgba(14,16,20,0)70%)'),
      'layout.css missing Google TV vertical scrim gradient');
  });

  await check('S1', '8', 'Live Clock initialization and textContent updates without innerHTML', async () => {
    const { document, app } = createHarness();
    const clock = document.getElementById('clock');
    assert(clock, '#clock element missing');
    app.initClock();
    assert(clock.textContent.length >= 4, '#clock textContent should contain formatted time');
  });

  await check('S1', '9', 'Global updateScrollState toggles .scrolled class on body and #app', async () => {
    const { window, document, app } = createHarness();
    const appEl = document.getElementById('app');

    app.updateScrollState(true);
    assert(document.body.classList.contains('scrolled'), 'body must have .scrolled when isScrolled=true');
    assert(appEl.classList.contains('scrolled'), '#app must have .scrolled when isScrolled=true');

    app.updateScrollState(false);
    assert(!document.body.classList.contains('scrolled'), 'body must not have .scrolled when isScrolled=false');
    assert(!appEl.classList.contains('scrolled'), '#app must not have .scrolled when isScrolled=false');
  });

  // ===========================================================================
  // SUITE 2: Top Bar Spatial Navigation & Focus Traversal
  // ===========================================================================
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 2: Top Bar Spatial Navigation & Focus Traversal${C.reset}`);

  await check('S2', '1', 'Header candidates discovery: exactly 4 tabs navigable, non-nav pills excluded', async () => {
    const { spatialNav, document } = createHarness();
    const candidates = spatialNav.getCandidates();
    const headerCandidates = candidates.filter(c => c.getAttribute('data-nav-group') === 'header');

    assert.strictEqual(headerCandidates.length, 4, `Expected 4 header candidates, got ${headerCandidates.length}`);
    const ids = headerCandidates.map(c => c.id);
    assert(ids.includes('header-nav-home'), 'Missing #header-nav-home');
    assert(ids.includes('header-nav-movies'), 'Missing #header-nav-movies');
    assert(ids.includes('header-nav-series'), 'Missing #header-nav-series');
    assert(ids.includes('header-nav-search'), 'Missing #header-nav-search');

    // Confirm avatar and settings are excluded from spatial nav candidates
    assert(!ids.includes('avatar'), 'Avatar must NOT be in navigable candidates');
    assert(!ids.includes('top-btn-settings'), 'Settings must NOT be in navigable candidates');
  });

  await check('S2', '2', 'Deterministic Horizontal D-Pad Traversal: Home -> Movies -> Shows -> Search', async () => {
    const { spatialNav, document } = createHarness();
    const homeTab = document.getElementById('header-nav-home');
    const moviesTab = document.getElementById('header-nav-movies');
    const seriesTab = document.getElementById('header-nav-series');
    const searchTab = document.getElementById('header-nav-search');

    spatialNav.setFocus(homeTab);
    assert.strictEqual(spatialNav.getCurrentFocus(), homeTab);

    // Right -> Movies
    spatialNav.resetThrottle();
    spatialNav.move('right');
    assert.strictEqual(spatialNav.getCurrentFocus(), moviesTab, `Expected Movies tab, got #${spatialNav.getCurrentFocus()?.id}`);

    // Right -> Shows
    spatialNav.resetThrottle();
    spatialNav.move('right');
    assert.strictEqual(spatialNav.getCurrentFocus(), seriesTab, `Expected Shows tab, got #${spatialNav.getCurrentFocus()?.id}`);

    // Right -> Search
    spatialNav.resetThrottle();
    spatialNav.move('right');
    assert.strictEqual(spatialNav.getCurrentFocus(), searchTab, `Expected Search tab, got #${spatialNav.getCurrentFocus()?.id}`);

    // Left -> Shows
    spatialNav.resetThrottle();
    spatialNav.move('left');
    assert.strictEqual(spatialNav.getCurrentFocus(), seriesTab, `Expected Shows tab on return, got #${spatialNav.getCurrentFocus()?.id}`);

    // Left -> Movies
    spatialNav.resetThrottle();
    spatialNav.move('left');
    assert.strictEqual(spatialNav.getCurrentFocus(), moviesTab, `Expected Movies tab on return, got #${spatialNav.getCurrentFocus()?.id}`);

    // Left -> Home
    spatialNav.resetThrottle();
    spatialNav.move('left');
    assert.strictEqual(spatialNav.getCurrentFocus(), homeTab, `Expected Home tab on return, got #${spatialNav.getCurrentFocus()?.id}`);
  });

  await check('S2', '3', 'Boundary Dead-End Stability: Right at Search tab and Up from Top Bar', async () => {
    const { spatialNav, document } = createHarness();
    const homeTab = document.getElementById('header-nav-home');
    const searchTab = document.getElementById('header-nav-search');

    // Right at Search boundary (no elements to the right)
    spatialNav.setFocus(searchTab);
    spatialNav.resetThrottle();
    spatialNav.move('right');
    assert.strictEqual(spatialNav.getCurrentFocus(), searchTab, 'Focus must remain on Search tab when moving right at boundary');

    // Up at Top Bar (no elements above y=44)
    spatialNav.resetThrottle();
    spatialNav.move('up');
    assert.strictEqual(spatialNav.getCurrentFocus(), searchTab, 'Focus must remain on Search tab when moving up at header boundary');

    // Up from Home tab
    spatialNav.setFocus(homeTab);
    spatialNav.resetThrottle();
    spatialNav.move('up');
    assert.strictEqual(spatialNav.getCurrentFocus(), homeTab, 'Focus must remain on Home tab when moving up at header boundary');
  });

  await check('S2', '4', 'Vertical Navigation: Header Tab DOWN to View Content and View UP to Header', async () => {
    const { spatialNav, document } = createHarness();
    const homeTab = document.getElementById('header-nav-home');
    spatialNav.setFocus(homeTab);

    // Down from Header into Home View
    spatialNav.resetThrottle();
    spatialNav.move('down');
    const focusedInView = spatialNav.getCurrentFocus();
    assert(focusedInView, 'Focus must move into Home view on ArrowDown');
    assert(focusedInView.getAttribute('data-nav-group') === 'hero' || focusedInView.id === 'hero-play-btn',
      `Expected hero element on down, got #${focusedInView.id}`);

    // Up from View element back to Header
    spatialNav.resetThrottle();
    spatialNav.move('up');
    const focusedBackHeader = spatialNav.getCurrentFocus();
    assert(focusedBackHeader, 'Focus must return to header on ArrowUp');
    assert.strictEqual(focusedBackHeader.getAttribute('data-nav-group'), 'header',
      `Expected header group, got #${focusedBackHeader.id}`);
  });

  await check('S2', '5', 'Key Repeat Burst Hammering: 50 Rapid Keypresses Maintain Engine Stability', async () => {
    const { spatialNav, document } = createHarness();
    const homeTab = document.getElementById('header-nav-home');
    spatialNav.setFocus(homeTab);

    const directions = ['right', 'left', 'right', 'down', 'up'];
    for (let i = 0; i < 50; i++) {
      spatialNav.move(directions[i % directions.length]);
    }
    const finalFocus = spatialNav.getCurrentFocus();
    assert(finalFocus, 'Engine must retain valid focused element after 50 rapid key bursts');
  });

  // ===========================================================================
  // SUITE 3: Route Transitions & View Synchronization
  // ===========================================================================
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 3: Route Transitions & Synchronization Integrity${C.reset}`);

  await check('S3', '1', 'Initial Boot Invariant: Exactly 1 view active, header indicator synchronized', async () => {
    const { document, app } = createHarness();
    const activeViews = document.querySelectorAll('.view.active');
    assert.strictEqual(activeViews.length, 1, `Expected exactly 1 active view, got ${activeViews.length}`);
    assert.strictEqual(activeViews[0].id, 'view-home');

    const homeTab = document.getElementById('header-nav-home');
    assert(homeTab.classList.contains('active'), 'Home tab must have .active');
    assert(homeTab.classList.contains('cur'), 'Home tab must have .cur');
    assert.strictEqual(homeTab.getAttribute('aria-selected'), 'true');

    const otherTabs = document.querySelectorAll('.nav-pill-item:not(#header-nav-home)');
    otherTabs.forEach(t => {
      assert(!t.classList.contains('active'), `${t.id} must not have .active`);
      assert.strictEqual(t.getAttribute('aria-selected'), 'false');
    });
  });

  await check('S3', '2', 'Systematic Route Cycling (home -> movies -> series -> search -> details -> home)', async () => {
    const { document, app } = createHarness();
    const routes = ['movies', 'series', 'search', 'details', 'home'];

    for (const r of routes) {
      app.switchView(r);
      assert.strictEqual(app.state.currentView, r, `Current view should be ${r}`);
      const activeViews = document.querySelectorAll('.view.active');
      assert.strictEqual(activeViews.length, 1, `Exactly 1 active view required on route ${r}`);
      assert.strictEqual(activeViews[0].id, 'view-' + r);

      // Verify header tab synchronization for top-level tabs
      const matchingTab = document.querySelector(`.nav-pill-item[data-route="${r}"]`);
      if (matchingTab) {
        assert(matchingTab.classList.contains('active'), `Tab ${matchingTab.id} must have .active`);
        assert.strictEqual(matchingTab.getAttribute('aria-selected'), 'true');
      }
    }
  });

  await check('S3', '3', 'Header Visibility State: Visible on normal routes, hidden on player', async () => {
    const { document, app } = createHarness();
    const header = document.getElementById('top');

    app.switchView('home');
    assert(!header.classList.contains('header-hidden'), 'Header must be visible on home');

    app.switchView('player');
    assert(header.classList.contains('header-hidden'), 'Header must have .header-hidden on player view');

    app.switchView('movies');
    assert(!header.classList.contains('header-hidden'), 'Header must be restored upon leaving player view');
  });

  await check('S3', '4', 'Rapid 100-Switch Randomized Route Fuzzing maintains single-active invariant', async () => {
    const { document, app } = createHarness();
    const allViews = ['home', 'movies', 'series', 'search', 'details', 'player'];

    for (let i = 0; i < 100; i++) {
      const target = allViews[Math.floor(Math.random() * allViews.length)];
      app.switchView(target);
      const activeCount = document.querySelectorAll('.view.active').length;
      assert.strictEqual(activeCount, 1, `Invariant broken on step ${i}: found ${activeCount} active views`);
    }
  });

  await check('S3', '5', 'Unknown route protection: unrecognized view does not mutate state or throw', async () => {
    const { document, app } = createHarness();
    const prevView = app.state.currentView;
    app.switchView('invalid-route-xyz');
    assert.strictEqual(app.state.currentView, prevView, 'Invalid route must be ignored');
  });

  await check('S3', '6', 'View Focus Memory: Departure focus saved and restored upon return', async () => {
    const { document, app, spatialNav } = createHarness();

    // Focus an element in Home view
    const heroBtn = document.getElementById('hero-play-btn');
    spatialNav.setFocus(heroBtn);
    assert.strictEqual(spatialNav.getCurrentFocus(), heroBtn);

    // Switch to Movies
    app.switchView('movies');
    assert.strictEqual(app.state.currentView, 'movies');

    // Switch back to Home
    app.switchView('home');
    assert.strictEqual(app.state.currentView, 'home');
    const restored = spatialNav.getCurrentFocus();
    assert(restored, 'Focus must be restored on return to Home view');
  });

  // ===========================================================================
  // SUITE 4: Media Player DOM Integrity & Lifecycle Robustness
  // ===========================================================================
  console.log(`\n${C.bold}${C.magenta}▶ SUITE 4: Media Player DOM Integrity & Video Lifecycle${C.reset}`);

  await check('S4', '1', '<video id="main-video-player"> exists with mandatory webOS attributes', async () => {
