  await check('S5', '1', 'Zero DOM Sinks: Exactly 0 occurrences of .innerHTML = or .outerHTML = in app/js/', async () => {
    const jsDir = path.resolve(__dirname, '../app/js');
    function scanFiles(dir) {
      let files = [];
      const entries = fs.readdirSync(dir, { withFileTypes: true });
      for (const entry of entries) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) {
          files = files.concat(scanFiles(full));
        } else if (entry.isFile() && entry.name.endsWith('.js')) {
          files.push(full);
        }
      }
      return files;
    }

    const jsFiles = scanFiles(jsDir);
    const sinkViolations = [];
    for (const file of jsFiles) {
      const content = fs.readFileSync(file, 'utf8');
      const lines = content.split('\n');
      lines.forEach((line, idx) => {
        if (/(\.innerHTML|\.outerHTML)\s*=[^=]/.test(line)) {
          sinkViolations.push(`${path.relative(jsDir, file)}:${idx + 1} -> ${line.trim()}`);
        }
      });
    }

    assert.strictEqual(sinkViolations.length, 0, `DOM Sink violations found:\n${sinkViolations.join('\n')}`);
  });

